// Pop out v2: vector shapes and the maths the transformations share.
// shapes.json is generated by trace_shapes.py (garment cut-out contours and the Curate mark, traced
// from their library files); everything here is pure functions of numbers.
import SHAPES from "./shapes.json";

export type Pt = [number, number];

/** Exponential and critically damped easings only (no overshoot anywhere). */
export const clamp01 = (t: number) => (t < 0 ? 0 : t > 1 ? 1 : t);
export const expoOut = (t: number) => (t <= 0 ? 0 : t >= 1 ? 1 : 1 - Math.pow(2, -10 * t));
export const expoIn = (t: number) => (t <= 0 ? 0 : t >= 1 ? 1 : Math.pow(2, 10 * (t - 1)) - 0.001 * (1 - t));
export const expoInOut = (t: number) => (t <= 0 ? 0 : t >= 1 ? 1 : t < 0.5 ? Math.pow(2, 20 * t - 10) / 2 : (2 - Math.pow(2, -20 * t + 10)) / 2);
const W = 9; // a critically damped spring, settled to 0.1% at t = 1
const CRIT_END = 1 - (1 + W) * Math.exp(-W);
export const crit = (t: number) => (t <= 0 ? 0 : t >= 1 ? 1 : (1 - (1 + W * t) * Math.exp(-W * t)) / CRIT_END);
/** 0..1 progress of frame f through [a, a + d]. */
export const tw = (f: number, a: number, d: number) => clamp01((f - a) / d);
export const lerp = (a: number, b: number, t: number) => a + (b - a) * t;

export const toPath = (p: Pt[], close = true) => "M" + p.map(([x, y]) => `${x.toFixed(2)} ${y.toFixed(2)}`).join("L") + (close ? "Z" : "");
export const lerpPts = (a: Pt[], b: Pt[], t: number): Pt[] => a.map((p, i) => [p[0] + (b[i][0] - p[0]) * t, p[1] + (b[i][1] - p[1]) * t]);
export const polyLen = (p: Pt[], closed = true) => {
  let s = 0;
  for (let i = 1; i < p.length; i++) s += Math.hypot(p[i][0] - p[i - 1][0], p[i][1] - p[i - 1][1]);
  if (closed) s += Math.hypot(p[0][0] - p[p.length - 1][0], p[0][1] - p[p.length - 1][1]);
  return s;
};

/** Resample a closed polygon to n points, evenly spaced along its length, keeping its start. */
export const resample = (p: Pt[], n: number): Pt[] => {
  const q = [...p, p[0]];
  const cum = [0];
  for (let i = 1; i < q.length; i++) cum.push(cum[i - 1] + Math.hypot(q[i][0] - q[i - 1][0], q[i][1] - q[i - 1][1]));
  const L = cum[cum.length - 1];
  const out: Pt[] = [];
  let j = 0;
  for (let k = 0; k < n; k++) {
    const s = (k / n) * L;
    while (j < cum.length - 2 && cum[j + 1] < s) j++;
    const u = (s - cum[j]) / Math.max(1e-9, cum[j + 1] - cum[j]);
    out.push([lerp(q[j][0], q[j + 1][0], u), lerp(q[j][1], q[j + 1][1], u)]);
  }
  return out;
};

/** n points along a polyline through `verts`, every vertex kept (so a lattice keeps its corners). */
export const alongPolyline = (verts: Pt[], n: number): Pt[] => {
  const seg = verts.slice(1).map((v, i) => Math.hypot(v[0] - verts[i][0], v[1] - verts[i][1]));
  const L = seg.reduce((a, b) => a + b, 0);
  const counts = seg.map((s) => Math.max(1, Math.round((s / L) * (n - 1))));
  let diff = n - 1 - counts.reduce((a, b) => a + b, 0);
  for (let i = 0; diff !== 0; i = (i + 1) % counts.length) {
    if (diff > 0) {
      counts[i]++;
      diff--;
    } else if (counts[i] > 1) {
      counts[i]--;
      diff++;
    }
  }
  const out: Pt[] = [];
  seg.forEach((_, i) => {
    for (let k = 0; k < counts[i]; k++) {
      const u = k / counts[i];
      out.push([lerp(verts[i][0], verts[i + 1][0], u), lerp(verts[i][1], verts[i + 1][1], u)]);
    }
  });
  out.push(verts[verts.length - 1]);
  return out;
};

/** A rounded rectangle as n points, clockwise from the middle of its top edge. */
export const roundedRect = (x: number, y: number, w: number, h: number, r: number, n: number): Pt[] => {
  const v: Pt[] = [];
  const arc = (cx: number, cy: number, a0: number) => {
    for (let k = 0; k <= 12; k++) {
      const a = a0 + (k / 12) * (Math.PI / 2);
      v.push([cx + r * Math.cos(a), cy + r * Math.sin(a)]);
    }
  };
  v.push([x + w / 2, y]);
  arc(x + w - r, y + r, -Math.PI / 2);
  arc(x + w - r, y + h - r, 0);
  arc(x + r, y + h - r, Math.PI / 2);
  arc(x + r, y + r, Math.PI);
  return resample(v, n);
};

export const N = SHAPES.n;

type G = { w: number; h: number; pts: number[][] };
const GARMENTS = SHAPES.garments as Record<string, G>;

/** A garment cut-out's aspect (w / h) as drawn. */
export const aspectOf = (id: string) => GARMENTS[id].w / GARMENTS[id].h;

/** A garment's contour, drawn `h` tall, centred on (cx, cy), rotated `rot` degrees. */
export const garmentPts = (id: string, cx: number, cy: number, h: number, rot = 0): Pt[] => {
  const g = GARMENTS[id];
  const w = h * (g.w / g.h);
  const c = Math.cos((rot * Math.PI) / 180);
  const s = Math.sin((rot * Math.PI) / 180);
  return g.pts.map(([u, v]) => {
    const x = (u - 0.5) * w;
    const y = (v - 0.5) * h;
    return [cx + x * c - y * s, cy + x * s + y * c];
  });
};

// The Curate mark, redrawn as vector from brand.curate.splash-mark.v1 (1152 px canvas).
const M = SHAPES.mark as { w: number; h: number; bbox: number[]; outlines: number[][][]; star: number[][] };
export const MARK_CANVAS = M.w;
export const MARK_BBOX = M.bbox; // [x0, y0, x1, y1] in canvas px
export const STAR_CENTRE: Pt = [576, 575]; // canvas px: the star's centre (and the mark's)
/** Mark outline(s) and the star, mapped so the star's centre lands on (cx, cy) at `px` screen px per canvas px. */
export const markPts = (cx: number, cy: number, px: number) =>
  M.outlines.map((o) => o.map(([u, v]) => [cx + (u * M.w - STAR_CENTRE[0]) * px, cy + (v * M.h - STAR_CENTRE[1]) * px] as Pt));
export const starPts = (cx: number, cy: number, px: number): Pt[] => M.star.map(([u, v]) => [cx + (u * M.w - STAR_CENTRE[0]) * px, cy + (v * M.h - STAR_CENTRE[1]) * px]);
